create table if not exists public.hr_recruit_rules (
  only_row      boolean  primary key default true check (only_row),
  at_level      integer  not null check (at_level >= 2),
  levels_under  integer  not null check (levels_under >= 0),
  max_level     integer  not null check (max_level >= 1),
  recruit_count integer  not null check (recruit_count between 1 and 5)
);
create table if not exists public.hr_recruit_jobs (
  rank   smallint primary key check (rank >= 1),
  set_id text     not null unique check (set_id ~ '^[a-z][a-z0-9_]{0,31}$')
);
create table if not exists public.hr_recruit_names (
  name text primary key check (name ~ '^[A-Z][a-z]{1,8}$'),
  part text not null check (part in ('given', 'family'))
);
alter table public.hr_recruit_rules enable row level security;
alter table public.hr_recruit_jobs enable row level security;
alter table public.hr_recruit_names enable row level security;
comment on table public.hr_recruit_rules is '1052-recruits-catalogue.generated.sql: when the recruits come and at what Level, generated from src/data/recruits.js RECRUITS. Read by hr_recruit_offer. Server-only.';
comment on table public.hr_recruit_jobs is '1052-recruits-catalogue.generated.sql: the STARTER_SETS ids a recruit may wear, in the order the company needs them (src/data/recruits.js RECRUITS.jobs). Server-only.';
comment on table public.hr_recruit_names is '1052-recruits-catalogue.generated.sql: the given and family names an unnamed recruit is named from (src/data/recruits.js). Server-only.';

delete from public.hr_recruit_rules;
delete from public.hr_recruit_jobs;
delete from public.hr_recruit_names;

-- ── Grants: the server's alone (revoke before nothing is granted) ─────────
revoke all on public.hr_recruit_rules from public, anon, authenticated;
revoke all on public.hr_recruit_jobs from public, anon, authenticated;
revoke all on public.hr_recruit_names from public, anon, authenticated;

-- ── Self-verification ────────────────────────────────────────────────────
do $$
declare v_bad text; v_role text;
begin
  if (select count(*) from public.hr_recruit_jobs) <> 4 or (select count(*) from public.hr_recruit_names) <> 72
     or (select count(*) from public.hr_recruit_rules) <> 1 then
    raise exception 'the recruit catalogue does not hold what the generator emitted';
  end if;
  -- every job is a practice set that wears a weapon
  select string_agg(j.set_id, ', ') into v_bad from public.hr_recruit_jobs j
   where not exists (select 1 from public.hr_start_kit_lines l where l.kit = 'practice' and l.set_id = j.set_id and l.worn and l.equip_slot = 'weapon');
  if v_bad is not null then raise exception 'hr_recruit_jobs names a set that is no practice set: %', v_bad; end if;
  if (select recruit_count from public.hr_recruit_rules) > (select count(*) from public.hr_recruit_jobs)
     or (select recruit_count from public.hr_recruit_rules) > (select count(*) from public.hr_hero_slots) then
    raise exception 'hr_recruit_rules asks for more recruits than jobs or slots';
  end if;
  -- every name the server may give passes the rules a player's name passes (moderation, reserved, length): a given name alone and with
  -- every family name
  select string_agg(x.nm, ', ') into v_bad from (
    select g.name as nm from public.hr_recruit_names g where g.part = 'given'
    union all
    select g.name || ' ' || f.name from public.hr_recruit_names g cross join public.hr_recruit_names f where g.part = 'given' and f.part = 'family'
  ) x where coalesce(public.hr_validate_display_name(x.nm)->>'ok', '') <> 'true';
  if v_bad is not null then raise exception 'a recruit name fails the name rules: %', left(v_bad, 400); end if;
  foreach v_role in array array['anon', 'authenticated'] loop
    if has_table_privilege(v_role, 'public.hr_recruit_rules', 'select,insert,update,delete')
       or has_table_privilege(v_role, 'public.hr_recruit_jobs', 'select,insert,update,delete')
       or has_table_privilege(v_role, 'public.hr_recruit_names', 'select,insert,update,delete') then
      raise exception 'the recruit catalogue is readable or writable by %', v_role;
    end if;
  end loop;
  raise notice 'hr_recruit_* OK — 4 jobs, 72 names, digest 07c09c0a45529f7663dd6ed8793c8ad431031736076937b71bb4fc542daf87aa';
end $$;
